def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    target_y = 11.7
    target_x_min = 9.35
    target_x_max = 10.65
    apex_velocity_threshold = 0.5  # m/s

    if pos.y < target_y:
        # Pumping phase: apply horizontal force when moving away from pivot
        if (pos.x < 10.0 and vx < 0) or (pos.x > 10.0 and vx > 0):
            fx = 42.0 if vx > 0 else -42.0
            sandbox.apply_force_to_seat(fx, 0)
    else:
        # Adjust x position to be in target range when near apex
        if abs(vy) < apex_velocity_threshold:
            if pos.x < target_x_min:
                # Push right to bring into target x range
                fx = 42.0
            elif pos.x > target_x_max:
                # Push left to bring into target x range
                fx = -42.0
            else:
                # Already in target x range, apply stabilizing force
                fx = -vx * 10.0
        else:
            # Not near apex, apply stabilizing force
            fx = -vx * 10.0
        sandbox.apply_force_to_seat(fx, 0)
